import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

class BoundedBlockingQueue<T> {
  private final Object[] items;
  private int head, tail, count;
  private final ReentrantLock lock = new ReentrantLock();
  private final Condition notFull = lock.newCondition();
  private final Condition notEmpty = lock.newCondition();

  public BoundedBlockingQueue(int capacity) {
    if (capacity <= 0) throw new IllegalArgumentException("capacity must be > 0");
    items = new Object[capacity];
  }

  public void put(T item) throws InterruptedException {
    if (item == null) throw new NullPointerException();
    lock.lockInterruptibly();
    try {
      while (count == items.length) notFull.await();   // while, not if: spurious wakeups / stolen slots
      enqueue(item);
    } finally {
      lock.unlock();
    }
  }

  public T take() throws InterruptedException {
    lock.lockInterruptibly();
    try {
      while (count == 0) notEmpty.await();
      return dequeue();
    } finally {
      lock.unlock();
    }
  }

  public boolean offer(T item, long timeout, TimeUnit unit) throws InterruptedException {
    if (item == null) throw new NullPointerException();
    long nanos = unit.toNanos(timeout);
    lock.lockInterruptibly();
    try {
      while (count == items.length) {
        if (nanos <= 0) return false;
        nanos = notFull.awaitNanos(nanos);   // returns remaining time
      }
      enqueue(item);
      return true;
    } finally {
      lock.unlock();
    }
  }

  public T poll(long timeout, TimeUnit unit) throws InterruptedException {
    long nanos = unit.toNanos(timeout);
    lock.lockInterruptibly();
    try {
      while (count == 0) {
        if (nanos <= 0) return null;
        nanos = notEmpty.awaitNanos(nanos);
      }
      return dequeue();
    } finally {
      lock.unlock();
    }
  }

  public int size() {
    lock.lock();
    try { return count; } finally { lock.unlock(); }
  }

  private void enqueue(T item) {
    items[tail] = item;
    tail = (tail + 1) % items.length;
    count++;
    notEmpty.signal();   // exactly one waiting consumer can make progress
  }

  @SuppressWarnings("unchecked")
  private T dequeue() {
    T item = (T) items[head];
    items[head] = null;   // let GC reclaim
    head = (head + 1) % items.length;
    count--;
    notFull.signal();
    return item;
  }
}

