import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.locks.ReentrantLock;

class LRUCache<K, V> {
  private static final class Node<K, V> {
    final K key; V value; Node<K, V> prev, next;
    Node(K key, V value) { this.key = key; this.value = value; }
  }

  private final int capacity;
  private final Map<K, Node<K, V>> map = new HashMap<>();
  private final Node<K, V> head = new Node<>(null, null);  // sentinel; most recent is head.next
  private final Node<K, V> tail = new Node<>(null, null);  // sentinel; least recent is tail.prev
  // One exclusive lock: get() mutates recency order, so a read lock would NOT be safe here.
  private final ReentrantLock lock = new ReentrantLock();

  public LRUCache(int capacity) {
    if (capacity <= 0) throw new IllegalArgumentException();
    this.capacity = capacity;
    head.next = tail;
    tail.prev = head;
  }

  public V get(K key) {
    lock.lock();
    try {
      Node<K, V> n = map.get(key);
      if (n == null) return null;
      unlink(n);
      linkFirst(n);
      return n.value;
    } finally {
      lock.unlock();
    }
  }

  public void put(K key, V value) {
    lock.lock();
    try {
      Node<K, V> n = map.get(key);
      if (n != null) {
        n.value = value;
        unlink(n);
        linkFirst(n);
        return;
      }
      if (map.size() == capacity) {
        Node<K, V> lru = tail.prev;
        unlink(lru);
        map.remove(lru.key);
      }
      n = new Node<>(key, value);
      map.put(key, n);
      linkFirst(n);
    } finally {
      lock.unlock();
    }
  }

  public int size() {
    lock.lock();
    try { return map.size(); } finally { lock.unlock(); }
  }

  private void unlink(Node<K, V> n) {
    n.prev.next = n.next;
    n.next.prev = n.prev;
  }

  private void linkFirst(Node<K, V> n) {
    n.next = head.next;
    n.prev = head;
    head.next.prev = n;
    head.next = n;
  }

  /** Used by tests: walk the list and verify it agrees with the map. */
  boolean checkInvariants() {
    lock.lock();
    try {
      int cnt = 0;
      for (Node<K, V> n = head.next; n != tail; n = n.next) {
        if (n.next.prev != n || map.get(n.key) != n) return false;
        cnt++;
      }
      return cnt == map.size() && cnt <= capacity;
    } finally {
      lock.unlock();
    }
  }
}

