import java.util.function.LongSupplier;

class TokenBucketRateLimiter {
  private final long capacity;
  private final double refillPerNano;
  private final LongSupplier clock;     // injectable for deterministic tests
  private double tokens;                // guarded by this
  private long lastRefill;              // guarded by this

  public TokenBucketRateLimiter(long capacity, double refillPerSecond) {
    this(capacity, refillPerSecond, System::nanoTime);
  }

  TokenBucketRateLimiter(long capacity, double refillPerSecond, LongSupplier nanoClock) {
    if (capacity <= 0 || refillPerSecond <= 0) throw new IllegalArgumentException();
    this.capacity = capacity;
    this.refillPerNano = refillPerSecond / 1_000_000_000.0;
    this.clock = nanoClock;
    this.tokens = capacity;             // start full
    this.lastRefill = nanoClock.getAsLong();
  }

  public boolean tryAcquire() { return tryAcquire(1); }

  public synchronized boolean tryAcquire(int permits) {
    if (permits <= 0 || permits > capacity) throw new IllegalArgumentException();
    refill();
    if (tokens >= permits) {            // check-then-act is atomic under the monitor
      tokens -= permits;
      return true;
    }
    return false;
  }

  public synchronized double availableTokens() {
    refill();
    return tokens;
  }

  private void refill() {
    long now = clock.getAsLong();
    long elapsed = now - lastRefill;    // nanoTime values are only meaningful as differences
    if (elapsed > 0) {
      tokens = Math.min(capacity, tokens + elapsed * refillPerNano);
      lastRefill = now;
    }
  }
}

