import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.locks.ReadWriteLock;
import java.util.concurrent.locks.ReentrantReadWriteLock;
import java.util.function.Function;

class LoadingCache<K, V> {
  private final Function<K, V> loader;
  private final Map<K, V> values = new HashMap<>();                         // guarded by rw
  private final Map<K, CompletableFuture<V>> inFlight = new HashMap<>();    // guarded by rw (write)
  private final ReadWriteLock rw = new ReentrantReadWriteLock();

  public LoadingCache(Function<K, V> loader) { this.loader = loader; }

  public V get(K key) throws InterruptedException {
    // 1) Fast path: concurrent readers share the read lock.
    rw.readLock().lock();
    try {
      V v = values.get(key);
      if (v != null) return v;
    } finally {
      rw.readLock().unlock();
    }

    // 2) Slow path: under the write lock, re-check and either join or become the loader.
    CompletableFuture<V> future;
    boolean leader = false;
    rw.writeLock().lock();
    try {
      V v = values.get(key);                    // double-check: another thread may have finished
      if (v != null) return v;
      future = inFlight.get(key);
      if (future == null) {
        future = new CompletableFuture<>();
        inFlight.put(key, future);
        leader = true;
      }
    } finally {
      rw.writeLock().unlock();
    }

    // 3) The leader runs the (slow) loader OUTSIDE any lock, so other keys are not blocked.
    if (leader) {
      try {
        V loaded = loader.apply(key);
        rw.writeLock().lock();
        try {
          values.put(key, loaded);
          inFlight.remove(key);
        } finally {
          rw.writeLock().unlock();
        }
        future.complete(loaded);
        return loaded;
      } catch (RuntimeException | Error e) {
        rw.writeLock().lock();
        try { inFlight.remove(key); } finally { rw.writeLock().unlock(); }   // allow retry
        future.completeExceptionally(e);
        throw e;
      }
    }

    // 4) Followers wait for the leader's result.
    try {
      return future.get();
    } catch (ExecutionException e) {
      Throwable c = e.getCause();
      if (c instanceof RuntimeException re) throw re;
      if (c instanceof Error err) throw err;
      throw new RuntimeException(c);
    }
  }

  public void invalidate(K key) {
    rw.writeLock().lock();
    try { values.remove(key); } finally { rw.writeLock().unlock(); }
  }
}

