import java.util.concurrent.TimeUnit;

class SimpleCountDownLatch {
  private long count;   // guarded by this

  public SimpleCountDownLatch(long count) {
    if (count < 0) throw new IllegalArgumentException("count < 0");
    this.count = count;
  }

  public synchronized void countDown() {
    if (count == 0) return;              // extra countDowns are no-ops
    if (--count == 0) notifyAll();       // wake ALL waiters, not just one
  }

  public synchronized void await() throws InterruptedException {
    while (count > 0) wait();            // loop guards against spurious wakeups
  }

  /** Returns true if the count reached zero, false if the timeout elapsed first. */
  public synchronized boolean await(long timeout, TimeUnit unit) throws InterruptedException {
    long deadline = System.nanoTime() + unit.toNanos(timeout);
    while (count > 0) {
      long remaining = deadline - System.nanoTime();
      if (remaining <= 0) return false;
      TimeUnit.NANOSECONDS.timedWait(this, remaining);
    }
    return true;
  }

  public synchronized long getCount() { return count; }
}

