import java.util.ArrayDeque;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Set;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;
import java.util.function.Supplier;

class ConnectionPool<C> {
  private final Supplier<C> factory;
  private final int maxSize;
  private final ArrayDeque<C> idle = new ArrayDeque<>();                                  // guarded by lock
  private final Set<C> leased = Collections.newSetFromMap(new IdentityHashMap<>());       // guarded by lock
  private int created;        // connections created OR reserved for creation; guarded by lock
  private boolean closed;     // guarded by lock
  private final ReentrantLock lock = new ReentrantLock(true);   // fair: FIFO-ish handoff to waiters
  private final Condition available = lock.newCondition();

  public ConnectionPool(Supplier<C> factory, int maxSize) {
    if (maxSize <= 0) throw new IllegalArgumentException();
    this.factory = factory;
    this.maxSize = maxSize;
  }

  public C acquire(long timeout, TimeUnit unit) throws InterruptedException, TimeoutException {
    long nanos = unit.toNanos(timeout);
    lock.lockInterruptibly();
    try {
      while (true) {
        if (closed) throw new IllegalStateException("pool closed");
        C c = idle.pollFirst();
        if (c != null) { leased.add(c); return c; }
        if (created < maxSize) { created++; break; }   // reserve a slot, create outside the lock
        if (nanos <= 0) throw new TimeoutException("no connection within timeout");
        nanos = available.awaitNanos(nanos);
      }
    } finally {
      lock.unlock();
    }
    // Slow I/O (connect) must not hold the pool lock.
    C c;
    try {
      c = factory.get();
    } catch (RuntimeException e) {
      lock.lock();
      try { created--; available.signal(); } finally { lock.unlock(); }   // give the slot back
      throw e;
    }
    lock.lock();
    try { leased.add(c); } finally { lock.unlock(); }
    return c;
  }

  public void release(C c) {
    lock.lock();
    try {
      if (!leased.remove(c)) throw new IllegalArgumentException("not leased from this pool");
      if (closed) { created--; return; }
      idle.addLast(c);
      available.signal();
    } finally {
      lock.unlock();
    }
  }

  public void close() {
    lock.lock();
    try {
      closed = true;
      created -= idle.size();
      idle.clear();
      available.signalAll();   // waiters must wake and observe closed
    } finally {
      lock.unlock();
    }
  }

  public int leasedCount() {
    lock.lock();
    try { return leased.size(); } finally { lock.unlock(); }
  }
}

