import java.util.concurrent.atomic.AtomicLongArray;

class StripedCounter {
  // Each logical cell occupies its own 64-byte region (8 longs) to avoid false sharing.
  private static final int PAD = 8;
  private final int mask;
  private final AtomicLongArray cells;

  public StripedCounter() { this(Runtime.getRuntime().availableProcessors()); }

  public StripedCounter(int stripes) {
    int n = 1;
    while (n < Math.max(1, stripes)) n <<= 1;   // power of two so we can mask instead of mod
    mask = n - 1;
    cells = new AtomicLongArray(n * PAD);
  }

  public void increment() { add(1); }

  public void add(long x) {
    int idx = index();
    // Fast path: one CAS on "our" stripe. On contention, move to another stripe and retry.
    for (int attempt = 0; ; attempt++) {
      int slot = ((idx + attempt) & mask) * PAD;
      long cur = cells.get(slot);
      if (cells.compareAndSet(slot, cur, cur + x)) return;
    }
  }

  /** Not an atomic snapshot: concurrent adds may or may not be included. Exact once writers quiesce. */
  public long sum() {
    long s = 0;
    for (int i = 0; i <= mask; i++) s += cells.get(i * PAD);
    return s;
  }

  public void reset() {
    for (int i = 0; i <= mask; i++) cells.set(i * PAD, 0);
  }

  private static int index() {
    // Spread the thread id so neighbouring ids do not cluster (Fibonacci hashing).
    long h = Thread.currentThread().threadId() * 0x9E3779B97F4A7C15L;
    return (int) (h >>> 32);
  }
}

