    }
  }

  /** Blocks if the queue is full (backpressure). Rejected after shutdown has begun. */
  public void submit(T item) throws InterruptedException {
    if (item == null) throw new NullPointerException();
    synchronized (submitLock) {
      if (shuttingDown) throw new IllegalStateException("shutting down");
      queue.put(item);
    }
  }

  /**
   * Graceful: every item submitted before this call is processed, then each consumer
   * receives exactly one pill and exits. Returns true if all consumers finished in time.
   */
  public boolean shutdownAndAwait(long timeout, TimeUnit unit) throws InterruptedException {
    synchronized (submitLock) {
      if (!shuttingDown) {
        shuttingDown = true;
        for (int i = 0; i < workers.size(); i++) queue.put(POISON);  // one pill PER consumer
      }
    }
    long deadline = System.nanoTime() + unit.toNanos(timeout);
    for (Thread t : workers) {
      long remaining = deadline - System.nanoTime();
      if (remaining <= 0) return false;
      TimeUnit.NANOSECONDS.timedJoin(t, remaining);
      if (t.isAlive()) return false;
    }
    return true;
  }

  @SuppressWarnings("unchecked")
  private void consumeLoop() {
    try {
      while (true) {
        Object o = queue.take();
        if (o == POISON) return;          // do not re-enqueue: each consumer owns one pill
        try {
          handler.accept((T) o);
        } catch (RuntimeException e) {
          // A bad item must not kill the consumer, or its pill would never be consumed.
          System.err.println("handler failed: " + e);
        }
      }
    } catch (InterruptedException e) {
      Thread.currentThread().interrupt();   // forced shutdown path: exit promptly
    }
  }
}

