import java.util.PriorityQueue;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

class DelayedTaskExecutor {
  private static final class Task implements Comparable<Task> {
    final long runAt;   // System.nanoTime() deadline
    final long seq;     // FIFO tie-break for equal deadlines
    final Runnable body;
    Task(long runAt, long seq, Runnable body) { this.runAt = runAt; this.seq = seq; this.body = body; }
    public int compareTo(Task o) {
      long d = runAt - o.runAt;          // overflow-safe nanoTime comparison
      if (d != 0) return d < 0 ? -1 : 1;
      return Long.compare(seq, o.seq);
    }
  }

  private final PriorityQueue<Task> heap = new PriorityQueue<>();   // guarded by lock
  private final ReentrantLock lock = new ReentrantLock();
  private final Condition changed = lock.newCondition();
  private final AtomicLong seq = new AtomicLong();
  private final Thread worker;
  private boolean shutdown;                                         // guarded by lock

  public DelayedTaskExecutor() {
    worker = new Thread(this::loop, "delayed-executor");
    worker.setDaemon(true);
    worker.start();
  }

  public void schedule(Runnable task, long delay, TimeUnit unit) {
    Task t = new Task(System.nanoTime() + unit.toNanos(Math.max(0, delay)), seq.getAndIncrement(), task);
    lock.lock();
    try {
      if (shutdown) throw new IllegalStateException("shut down");
      heap.add(t);
      // Only the head matters to the sleeper: wake it if the new task is now earliest.
      if (heap.peek() == t) changed.signal();
    } finally {
      lock.unlock();
    }
  }

  /** Stops accepting tasks; pending tasks are discarded; waits for a running task to finish. */
  public void shutdown() throws InterruptedException {
    lock.lock();
    try {
      shutdown = true;
      heap.clear();
      changed.signal();
    } finally {
      lock.unlock();
    }
    worker.join();
  }

  private void loop() {
    while (true) {
      Task next;
      lock.lock();
      try {
        while (true) {
          if (shutdown) return;
          Task head = heap.peek();
          if (head == null) { changed.await(); continue; }
          long wait = head.runAt - System.nanoTime();
          if (wait <= 0) { next = heap.poll(); break; }
          changed.awaitNanos(wait);   // woken early by an earlier schedule() or shutdown
        }
      } catch (InterruptedException e) {
        return;
      } finally {
        lock.unlock();
      }
      try {
        next.body.run();              // run OUTSIDE the lock so schedule() never blocks on a task
      } catch (RuntimeException e) {
        System.err.println("task failed: " + e);   // a failing task must not kill the worker
      }
    }
  }
}

