import java.util.List;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Function;

class WebCrawler {
  private final Function<String, List<String>> fetchLinks;   // blocking I/O, thread-safe
  private final int parallelism;

  public WebCrawler(Function<String, List<String>> fetchLinks, int parallelism) {
    if (parallelism <= 0) throw new IllegalArgumentException();
    this.fetchLinks = fetchLinks;
    this.parallelism = parallelism;
  }

  /** Crawls every URL reachable from startUrl on the same host; each URL is fetched at most once. */
  public Set<String> crawl(String startUrl) throws InterruptedException {
    String host = hostOf(startUrl);
    Set<String> seen = ConcurrentHashMap.newKeySet();
    AtomicInteger pending = new AtomicInteger();          // submitted-but-unfinished tasks
    Object done = new Object();
    ExecutorService pool = Executors.newFixedThreadPool(parallelism);  // bounds concurrent fetches
    try {
      seen.add(startUrl);
      pending.incrementAndGet();
      submit(pool, startUrl, host, seen, pending, done);
      synchronized (done) {
        while (pending.get() > 0) done.wait();            // termination: no task in flight
      }
    } finally {
      pool.shutdownNow();
      pool.awaitTermination(5, TimeUnit.SECONDS);
    }
    return seen;
  }

  private void submit(ExecutorService pool, String url, String host, Set<String> seen,
                      AtomicInteger pending, Object done) {
    pool.execute(() -> {
      try {
        List<String> links;
        try {
          links = fetchLinks.apply(url);
        } catch (RuntimeException e) {
          links = List.of();                              // one bad page must not hang the crawl
        }
        for (String next : links) {
          // add() is the atomic dedup gate: exactly one thread wins per URL.
          if (hostOf(next).equals(host) && seen.add(next)) {
            pending.incrementAndGet();                    // increment BEFORE our own decrement
            submit(pool, next, host, seen, pending, done);
          }
        }
      } finally {
        if (pending.decrementAndGet() == 0) {
          synchronized (done) { done.notifyAll(); }
        }
      }
    });
  }

  static String hostOf(String url) {
    int start = url.indexOf("://");
    start = start < 0 ? 0 : start + 3;
    int end = url.indexOf('/', start);
    return end < 0 ? url.substring(start) : url.substring(start, end);
  }
}
